    assign bridge_id_ar = BRIDGE_ID_WIDTH'(BRIDGE_ID);

    // ================================================================
    // Width adaptation - Master: 128b
    // Connected to slaves with widths: [128]
    // ================================================================

    // Per-width path-active gates (see comment in adapter_generator.py).
    logic aw_gate_ok;
    logic ar_gate_ok;
    logic aw_path_active_128b;
    assign aw_path_active_128b = (comb_slave_select_aw[0] | comb_slave_select_aw[1] | comb_slave_select_aw[2]) && aw_gate_ok;
    logic w_path_active_128b;
    assign w_path_active_128b = w_slave_select[0] | w_slave_select[1] | w_slave_select[2];
    logic ar_path_active_128b;
    assign ar_path_active_128b = (comb_slave_select_ar[0] | comb_slave_select_ar[1] | comb_slave_select_ar[2]) && ar_gate_ok;
    logic b_path_active_128b;
    assign b_path_active_128b = b_slave_select[0] | b_slave_select[1] | b_slave_select[2];
    logic r_path_active_128b;
    assign r_path_active_128b = r_slave_select[0] | r_slave_select[1] | r_slave_select[2];

    // ================================================================
    // Direct passthrough: 128b → 128b (no converter)
    // Requests: fub_axi_* → dma_128b_*
    // Responses: dma_128b_* → MUX → fub_axi_*
    // ================================================================

    // AW channel (request: fub → output)
    assign dma_128b_aw.id     = xbar_axi_awid;
    assign dma_128b_aw.addr   = fub_axi_awaddr;
    assign dma_128b_aw.len    = fub_axi_awlen;
    assign dma_128b_aw.size   = fub_axi_awsize;
    assign dma_128b_aw.burst  = fub_axi_awburst;
    assign dma_128b_aw.lock   = fub_axi_awlock;
    assign dma_128b_aw.cache  = fub_axi_awcache;
    assign dma_128b_aw.prot   = fub_axi_awprot;
    assign dma_128b_aw.qos    = fub_axi_awqos;
    assign dma_128b_aw.region = 4'b0;  // AXI5 has no REGION
    assign dma_128b_aw.user   = fub_axi_awuser;
    assign dma_128b_aw.nsaid = fub_axi_awnsaid;  // AXI5 sideband
    assign dma_128b_aw.trace = fub_axi_awtrace;  // AXI5 sideband
    assign dma_128b_aw.idunq = fub_axi_awidunq;  // AXI5 sideband
    assign dma_128b_aw.tagop = fub_axi_awtagop;  // AXI5 sideband
    assign dma_128b_awvalid   = fub_axi_awvalid && aw_path_active_128b;
    // awready routed via MUX

    // W channel (request: fub → output)
    assign dma_128b_w.data  = fub_axi_wdata;
    assign dma_128b_w.strb  = fub_axi_wstrb;
    assign dma_128b_w.last  = fub_axi_wlast;
    assign dma_128b_w.user  = fub_axi_wuser;
    assign dma_128b_w.poison = fub_axi_wpoison;  // AXI5 sideband
    assign dma_128b_w.tag = fub_axi_wtag;  // AXI5 sideband
    assign dma_128b_w.tagupdate = fub_axi_wtagupdate;  // AXI5 sideband
    assign dma_128b_wvalid  = fub_axi_wvalid && w_path_active_128b;
    // wready routed via MUX

    // B channel (response: output → MUX → fub)
    // Ready gated by the response head — see b_path_active comment.
    assign dma_128b_bready = fub_axi_bready && b_path_active_128b;
    // bid, bresp, bvalid routed via MUX (user field ignored)

    // AR channel (request: fub → output)
    assign dma_128b_ar.id     = xbar_axi_arid;
    assign dma_128b_ar.addr   = fub_axi_araddr;
    assign dma_128b_ar.len    = fub_axi_arlen;
    assign dma_128b_ar.size   = fub_axi_arsize;
    assign dma_128b_ar.burst  = fub_axi_arburst;
    assign dma_128b_ar.lock   = fub_axi_arlock;
    assign dma_128b_ar.cache  = fub_axi_arcache;
    assign dma_128b_ar.prot   = fub_axi_arprot;
    assign dma_128b_ar.qos    = fub_axi_arqos;
    assign dma_128b_ar.region = 4'b0;  // AXI5 has no REGION
    assign dma_128b_ar.user   = fub_axi_aruser;
    assign dma_128b_ar.nsaid = fub_axi_arnsaid;  // AXI5 sideband
    assign dma_128b_ar.trace = fub_axi_artrace;  // AXI5 sideband
    assign dma_128b_ar.idunq = fub_axi_aridunq;  // AXI5 sideband
    assign dma_128b_ar.chunken = fub_axi_archunken;  // AXI5 sideband
    assign dma_128b_ar.tagop = fub_axi_artagop;  // AXI5 sideband
    assign dma_128b_arvalid   = fub_axi_arvalid && ar_path_active_128b;
    // arready routed via MUX

    // R channel (response: output → MUX → fub)
    // Ready gated by the response head — see r_path_active comment.
    assign dma_128b_rready = fub_axi_rready && r_path_active_128b;
    // rid, rdata, rresp, rlast, rvalid routed via MUX (user field ignored)

    // ================================================================
    // Response MUX - Route responses from width-specific paths
    // back to fub_axi_* based on address decode
    //
    // Request side (arready/awready/wready) uses the combinational
    // slave_select_{ar,aw} (valid while {ar,aw}valid is asserted).
    //
    // Response side (rvalid/rdata/..., bvalid/bid/...) cannot reuse
    // the combinational decode because fub_axi_{ar,aw}addr no longer
    // holds the request address once the {AR,AW} handshake completes
    // -- the decode reverts (typically to slave 0) and drops the
    // response. So we track slave_select_{ar,aw} per outstanding
    // request in a small FIFO captured at handshake, popped at
    // R-last / B; the FIFO head drives the response MUX.
    // ================================================================

    // OUTPUT slave_select_aw mirrors the live combinational decode.
    assign slave_select_aw = comb_slave_select_aw;

    localparam int AW_TRK_DEPTH = 16;
    localparam int AW_TRK_AW    = 4;
    // -------- AW per-ID target table (fixes bridge GitHub #119 L1) --------
    // 16 entries indexed by the ID's low 4 bit(s). An ID with requests
    // in flight may only add more to the SAME slave (AXI same-ID order);
    // any other ID may go to any slave. IDs that share the index bits are
    // treated as one ID: safe, at worst a needless stall.
    localparam int AW_IDT_N = 16;
    logic [AW_TRK_AW:0]   aw_idt_cnt [AW_IDT_N];
    logic [NUM_SLAVES-1:0] aw_idt_tgt [AW_IDT_N];
    logic [AW_TRK_AW:0]   aw_out_cnt;
    // Next counts, and registered flags taken from them, so the gate a
    // request sees is a 1-bit lookup and a one-hot AND, not a counter
    // mux and compare in series with the crossbar's arbitration.
    logic [AW_TRK_AW:0]   aw_idt_cnt_nx [AW_IDT_N];
    logic [AW_TRK_AW:0]   aw_out_cnt_nx;
    logic [AW_IDT_N-1:0] aw_idt_busy;
    logic                  aw_trk_full;
    logic [3:0] aw_idt_widx, aw_idt_ridx;
    logic                  aw_idt_trace [AW_IDT_N];  // trace of the in-flight ID
    logic aw_idt_push, aw_idt_pop;
    assign aw_idt_widx = fub_axi_awid[3:0];
    assign aw_idt_ridx = fub_axi_bid[3:0];
    assign aw_idt_push = fub_axi_awvalid && fub_axi_awready;
    assign aw_idt_pop  = fub_axi_bvalid && fub_axi_bready;

    always_comb begin
        for (int i = 0; i < AW_IDT_N; i++) begin
            aw_idt_cnt_nx[i] = aw_idt_cnt[i]
                + (AW_TRK_AW+1)'(aw_idt_push && (aw_idt_widx == 4'(i)))
                - (AW_TRK_AW+1)'(aw_idt_pop  && (aw_idt_ridx == 4'(i)));
        end
        aw_out_cnt_nx = aw_out_cnt + (AW_TRK_AW+1)'(aw_idt_push)
                          - (AW_TRK_AW+1)'(aw_idt_pop);
    end

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AW_IDT_N; i++) begin
                aw_idt_cnt[i] <= '0;
                aw_idt_tgt[i] <= '0;
                aw_idt_trace[i] <= 1'b0;
            end
            aw_idt_busy <= '0;
            aw_out_cnt <= '0;
            aw_trk_full <= 1'b0;
        end else begin
            if (aw_idt_push) aw_idt_tgt[aw_idt_widx] <= comb_slave_select_aw;
            if (aw_idt_push) aw_idt_trace[aw_idt_widx] <= fub_axi_awtrace;
            for (int i = 0; i < AW_IDT_N; i++) begin
                aw_idt_cnt[i]  <= aw_idt_cnt_nx[i];
                aw_idt_busy[i] <= (aw_idt_cnt_nx[i] != '0);
            end
            aw_out_cnt  <= aw_out_cnt_nx;
            aw_trk_full <= (aw_out_cnt_nx == (AW_TRK_AW+1)'(AW_TRK_DEPTH));
        end
    )

    // bridge BUG-009 (was BRIDGE-011): a bounded number in flight, so no
    // count wraps; AW_TRK_DEPTH is the port's outstanding limit.
    // Target match is a one-hot AND: the stored target and the decode
    // are both one-hot (no hit selects the catch-all).
    logic aw_id_ok;
    assign aw_id_ok    = !aw_idt_busy[aw_idt_widx] ||
                           ((|(aw_idt_tgt[aw_idt_widx] & comb_slave_select_aw)) &&
                            (aw_idt_trace[aw_idt_widx] == fub_axi_awtrace));

    // One width path: every response arrives on it; the crossbar has
    // already chosen among the slaves behind it.
    assign b_slave_select = 3'b001;

    // bridge BUG-010 (was BRIDGE-012): the B echoes its request's trace,
    // looked up by the returning ID (single-valued per in-flight ID).
    logic b_trk_trace;
    assign b_trk_trace = aw_idt_trace[aw_idt_ridx];

    // -------- AW->W slave_select tracking FIFO --------
    // Same push as AW (records slave_select at handshake);
    // pops on wlast so W#2's path-active gating doesn't wait
    // for B#1 to return. Without this, back-to-back writes
    // to different-width slaves stamp W#2's data on AW#1's
    // bucket (see multi-master 128b->32b/128b regression).
    logic [NUM_SLAVES-1:0] w_trk_mem [AW_TRK_DEPTH];
    logic [AW_TRK_AW:0] w_trk_wptr, w_trk_rptr;
    logic w_trk_push, w_trk_pop;

    assign w_trk_push = fub_axi_awvalid && fub_axi_awready;
    assign w_trk_pop  = fub_axi_wvalid && fub_axi_wready && fub_axi_wlast;

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            w_trk_wptr <= '0;
            w_trk_rptr <= '0;
        end else begin
            if (w_trk_push) begin
                w_trk_mem[w_trk_wptr[AW_TRK_AW-1:0]] <= comb_slave_select_aw;
                w_trk_wptr <= w_trk_wptr + 1'b1;
            end
            if (w_trk_pop) begin
                w_trk_rptr <= w_trk_rptr + 1'b1;
            end
        end
    )

    assign w_slave_select = (w_trk_wptr != w_trk_rptr)
                          ? w_trk_mem[w_trk_rptr[AW_TRK_AW-1:0]]
                          : '0;

    // A new AW may target a different slave only once every W burst
    // already accepted has gone: W carries no ID and follows AW order,
    // so two masters each with W owed to two slaves could otherwise
    // wait on each other at the slaves' W ports (crossed W deadlock).
    assign aw_gate_ok = aw_id_ok && !aw_trk_full &&
                        ((w_trk_wptr == w_trk_rptr) ||
                         (|(w_slave_select & comb_slave_select_aw)));

    // OUTPUT slave_select_ar mirrors the live combinational decode.
    assign slave_select_ar = comb_slave_select_ar;

    localparam int AR_TRK_DEPTH = 16;
    localparam int AR_TRK_AW    = 4;
    // -------- AR per-ID target table (fixes bridge GitHub #119 L1) --------
    // 16 entries indexed by the ID's low 4 bit(s). An ID with requests
    // in flight may only add more to the SAME slave (AXI same-ID order);
    // any other ID may go to any slave. IDs that share the index bits are
    // treated as one ID: safe, at worst a needless stall.
    localparam int AR_IDT_N = 16;
    logic [AR_TRK_AW:0]   ar_idt_cnt [AR_IDT_N];
    logic [NUM_SLAVES-1:0] ar_idt_tgt [AR_IDT_N];
    logic [AR_TRK_AW:0]   ar_out_cnt;
    // Next counts, and registered flags taken from them, so the gate a
    // request sees is a 1-bit lookup and a one-hot AND, not a counter
    // mux and compare in series with the crossbar's arbitration.
    logic [AR_TRK_AW:0]   ar_idt_cnt_nx [AR_IDT_N];
    logic [AR_TRK_AW:0]   ar_out_cnt_nx;
    logic [AR_IDT_N-1:0] ar_idt_busy;
    logic                  ar_trk_full;
    logic [3:0] ar_idt_widx, ar_idt_ridx;
    logic                  ar_idt_trace [AR_IDT_N];  // trace of the in-flight ID
    logic ar_idt_push, ar_idt_pop;
    assign ar_idt_widx = fub_axi_arid[3:0];
    assign ar_idt_ridx = fub_axi_rid[3:0];
    assign ar_idt_push = fub_axi_arvalid && fub_axi_arready;
    assign ar_idt_pop  = fub_axi_rvalid && fub_axi_rready && fub_axi_rlast;

    always_comb begin
        for (int i = 0; i < AR_IDT_N; i++) begin
            ar_idt_cnt_nx[i] = ar_idt_cnt[i]
                + (AR_TRK_AW+1)'(ar_idt_push && (ar_idt_widx == 4'(i)))
                - (AR_TRK_AW+1)'(ar_idt_pop  && (ar_idt_ridx == 4'(i)));
        end
        ar_out_cnt_nx = ar_out_cnt + (AR_TRK_AW+1)'(ar_idt_push)
                          - (AR_TRK_AW+1)'(ar_idt_pop);
    end

    `ALWAYS_FF_RST(aclk, aresetn,
        if (`RST_ASSERTED(aresetn)) begin
            for (int i = 0; i < AR_IDT_N; i++) begin
                ar_idt_cnt[i] <= '0;
                ar_idt_tgt[i] <= '0;
                ar_idt_trace[i] <= 1'b0;
            end
            ar_idt_busy <= '0;
            ar_out_cnt <= '0;
            ar_trk_full <= 1'b0;
        end else begin
            if (ar_idt_push) ar_idt_tgt[ar_idt_widx] <= comb_slave_select_ar;
            if (ar_idt_push) ar_idt_trace[ar_idt_widx] <= fub_axi_artrace;
            for (int i = 0; i < AR_IDT_N; i++) begin
                ar_idt_cnt[i]  <= ar_idt_cnt_nx[i];
                ar_idt_busy[i] <= (ar_idt_cnt_nx[i] != '0);
            end
            ar_out_cnt  <= ar_out_cnt_nx;
            ar_trk_full <= (ar_out_cnt_nx == (AR_TRK_AW+1)'(AR_TRK_DEPTH));
        end
    )

    // bridge BUG-009 (was BRIDGE-011): a bounded number in flight, so no
    // count wraps; AR_TRK_DEPTH is the port's outstanding limit.
    // Target match is a one-hot AND: the stored target and the decode
    // are both one-hot (no hit selects the catch-all).
    logic ar_id_ok;
    assign ar_id_ok    = !ar_idt_busy[ar_idt_widx] ||
                           ((|(ar_idt_tgt[ar_idt_widx] & comb_slave_select_ar)) &&
                            (ar_idt_trace[ar_idt_widx] == fub_axi_artrace));
    assign ar_gate_ok = ar_id_ok && !ar_trk_full;

    // One width path: every response arrives on it; the crossbar has
    // already chosen among the slaves behind it.
    assign r_slave_select = 3'b001;

    // bridge BUG-010: the R echoes its request's trace (an atomic's AW trace).
    logic r_trk_trace;
    assign r_trk_trace = ar_idt_trace[ar_idt_ridx];

    // AW-ready MUX (combinational comb_slave_select_aw — awaddr is live during awvalid)
    always_comb begin
        fub_axi_awready = 1'b0;
        case (comb_slave_select_aw)
            3'b001: begin  // Slave 0 (128b)
                fub_axi_awready = dma_128b_awready;
            end
            3'b010: begin  // Slave 1 (128b)
                fub_axi_awready = dma_128b_awready;
            end
            3'b100: begin  // Slave 2 (128b)
                fub_axi_awready = dma_128b_awready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Hold off a new AW the gate refuses (see aw_gate_ok).
        if (!aw_gate_ok) fub_axi_awready = 1'b0;
    end

    // W-ready MUX (FIFO-tracked w_slave_select — awaddr has already reverted by W phase)
    always_comb begin
        fub_axi_wready = 1'b0;
        case (w_slave_select)
            3'b001: begin  // Slave 0 (128b)
                fub_axi_wready = dma_128b_wready;
            end
            3'b010: begin  // Slave 1 (128b)
                fub_axi_wready = dma_128b_wready;
            end
            3'b100: begin  // Slave 2 (128b)
                fub_axi_wready = dma_128b_wready;
            end
            default: begin
                // No active W transaction
            end
        endcase
    end

    // Write response MUX (B channel - uses b_slave_select FIFO head)
    // btrace is NOT driven here: the mux records what the SLAVE said
    // (checked below) while the port echoes the request (bridge BUG-010, was BRIDGE-012).
    logic b_slave_trace;
    always_comb begin
        fub_axi_bid = 4'd0;
        fub_axi_bresp = 2'b00;
        fub_axi_bvalid = 1'b0;
        b_slave_trace = '0;  // AXI5 sideband (trace)
        fub_axi_btagmatch = '0;  // AXI5 sideband (mte)

        case (b_slave_select)
            3'b001: begin  // Slave 0 (128b)
                fub_axi_bid = dma_128b_b.id[3:0];
                fub_axi_bresp = dma_128b_b.resp;
                fub_axi_bvalid = dma_128b_bvalid;
                b_slave_trace = dma_128b_b.trace;
                fub_axi_btagmatch = dma_128b_b.tagmatch;
            end
            3'b010: begin  // Slave 1 (128b)
                fub_axi_bid = dma_128b_b.id[3:0];
                fub_axi_bresp = dma_128b_b.resp;
                fub_axi_bvalid = dma_128b_bvalid;
                b_slave_trace = dma_128b_b.trace;
                fub_axi_btagmatch = dma_128b_b.tagmatch;
            end
            3'b100: begin  // Slave 2 (128b)
                fub_axi_bid = dma_128b_b.id[3:0];
                fub_axi_bresp = dma_128b_b.resp;
                fub_axi_bvalid = dma_128b_bvalid;
                b_slave_trace = dma_128b_b.trace;
                fub_axi_btagmatch = dma_128b_b.tagmatch;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end


    // bridge BUG-010 (was BRIDGE-012): the port promises trace; echo the request's bit.
    assign fub_axi_btrace = b_trk_trace;

`ifndef SYNTHESIS
    // A slave that DOES implement trace must echo it too. Echoing at the
    // boundary keeps this port correct whatever the slave does, but it
    // must not launder a trace-capable slave that returns the wrong bit.
    localparam logic [NUM_SLAVES-1:0] B_TRACE_CAPABLE = 3'b000;
    always_ff @(posedge aclk) begin
        if (aresetn && fub_axi_bvalid && fub_axi_bready &&
            |(b_slave_select & B_TRACE_CAPABLE) &&
            (b_slave_trace !== b_trk_trace)) begin
            $error("%m: bridge BUG-010 (was BRIDGE-012): trace-capable slave returned btrace=%b for a request with trace=%b",
                   b_slave_trace, b_trk_trace);
        end
    end
`endif

    // AR-ready MUX (request side: uses combinational comb_slave_select_ar)
    always_comb begin
        fub_axi_arready = 1'b0;
        case (comb_slave_select_ar)
            3'b001: begin  // Slave 0 (128b)
                fub_axi_arready = dma_128b_arready;
            end
            3'b010: begin  // Slave 1 (128b)
                fub_axi_arready = dma_128b_arready;
            end
            3'b100: begin  // Slave 2 (128b)
                fub_axi_arready = dma_128b_arready;
            end
            default: begin
                // No slave selected
            end
        endcase
        // Hold off a new AR the gate refuses (see ar_gate_ok).
        if (!ar_gate_ok) fub_axi_arready = 1'b0;
    end

    // Read response MUX (R channel - uses r_slave_select FIFO head)
    // rtrace is NOT driven here -- see the B-channel note (bridge BUG-010, was BRIDGE-012).
    logic r_slave_trace;
    always_comb begin
        fub_axi_rid = 4'd0;
        fub_axi_rdata = 128'd0;
        fub_axi_rresp = 2'b00;
        fub_axi_rlast = 1'b0;
        fub_axi_rvalid = 1'b0;
        r_slave_trace = '0;  // AXI5 sideband (trace)
        fub_axi_rpoison = '0;  // AXI5 sideband (poison)
        fub_axi_rchunkv = '0;  // AXI5 sideband (chunking)
        fub_axi_rchunknum = '0;  // AXI5 sideband (chunking)
        fub_axi_rchunkstrb = '0;  // AXI5 sideband (chunking)
        fub_axi_rtag = '0;  // AXI5 sideband (mte)

        case (r_slave_select)
            3'b001: begin  // Slave 0 (128b)
                fub_axi_rid = dma_128b_r.id[3:0];
                fub_axi_rdata = dma_128b_r.data;
                fub_axi_rresp = dma_128b_r.resp;
                fub_axi_rlast = dma_128b_r.last;
                fub_axi_rvalid = dma_128b_rvalid;
                r_slave_trace = dma_128b_r.trace;
                fub_axi_rpoison = dma_128b_r.poison;
                fub_axi_rchunkv = dma_128b_r.chunkv;
                fub_axi_rchunknum = dma_128b_r.chunknum;
                fub_axi_rchunkstrb = dma_128b_r.chunkstrb;
                fub_axi_rtag = dma_128b_r.tag;
            end
            3'b010: begin  // Slave 1 (128b)
                fub_axi_rid = dma_128b_r.id[3:0];
                fub_axi_rdata = dma_128b_r.data;
                fub_axi_rresp = dma_128b_r.resp;
                fub_axi_rlast = dma_128b_r.last;
                fub_axi_rvalid = dma_128b_rvalid;
                r_slave_trace = dma_128b_r.trace;
                fub_axi_rpoison = dma_128b_r.poison;
                fub_axi_rchunkv = dma_128b_r.chunkv;
                fub_axi_rchunknum = dma_128b_r.chunknum;
                fub_axi_rchunkstrb = dma_128b_r.chunkstrb;
                fub_axi_rtag = dma_128b_r.tag;
            end
            3'b100: begin  // Slave 2 (128b)
                fub_axi_rid = dma_128b_r.id[3:0];
                fub_axi_rdata = dma_128b_r.data;
                fub_axi_rresp = dma_128b_r.resp;
                fub_axi_rlast = dma_128b_r.last;
                fub_axi_rvalid = dma_128b_rvalid;
                r_slave_trace = dma_128b_r.trace;
                fub_axi_rpoison = dma_128b_r.poison;
                fub_axi_rchunkv = dma_128b_r.chunkv;
                fub_axi_rchunknum = dma_128b_r.chunknum;
                fub_axi_rchunkstrb = dma_128b_r.chunkstrb;
                fub_axi_rtag = dma_128b_r.tag;
            end
            default: begin
                // No slave selected - hold defaults
            end
        endcase
    end


    // bridge BUG-010 (was BRIDGE-012): the port promises trace; echo the request's bit.
    assign fub_axi_rtrace = r_trk_trace;

`ifndef SYNTHESIS
    // A slave that DOES implement trace must echo it too. Echoing at the
    // boundary keeps this port correct whatever the slave does, but it
    // must not launder a trace-capable slave that returns the wrong bit.
    localparam logic [NUM_SLAVES-1:0] R_TRACE_CAPABLE = 3'b000;
    always_ff @(posedge aclk) begin
        if (aresetn && fub_axi_rvalid && fub_axi_rready &&
            |(r_slave_select & R_TRACE_CAPABLE) &&
            (r_slave_trace !== r_trk_trace)) begin
            $error("%m: bridge BUG-010 (was BRIDGE-012): trace-capable slave returned rtrace=%b for a request with trace=%b",
                   r_slave_trace, r_trk_trace);
        end
    end
`endif


    // -------- ILA observation taps (AMBER_ILA_DBG builds only) --------
    // Amber bring-up round 5: name the adapter-internal AR tracker,
    // AR gate, and read-wrapper terms post-synth so the board ILA can
    // distinguish a corrupted ar_trk_full from a wedged axi4_slave_rd.
    // Pure observation; compiled out unless AMBER_ILA_DBG is defined.
`ifdef AMBER_ILA_DBG
    (* mark_debug = "true" *) logic             dbg_ad_ar_trk_full;
    (* mark_debug = "true" *) logic [AR_TRK_AW:0] dbg_ad_ar_out_cnt;
    (* mark_debug = "true" *) logic             dbg_ad_ar_gate_ok;
    (* mark_debug = "true" *) logic             dbg_ad_ar_push;
    (* mark_debug = "true" *) logic             dbg_ad_ar_pop;
    (* mark_debug = "true" *) logic             dbg_ad_host_arvalid;
    (* mark_debug = "true" *) logic             dbg_ad_host_arready;
    (* mark_debug = "true" *) logic             dbg_ad_fub_arvalid;
    (* mark_debug = "true" *) logic             dbg_ad_fub_arready;
    (* mark_debug = "true" *) logic             dbg_ad_wrapper_rd_busy;
    (* mark_debug = "true" *) logic             dbg_ad_fub_rvalid;
    (* mark_debug = "true" *) logic             dbg_ad_fub_rready;
    (* mark_debug = "true" *) logic             dbg_ad_fub_rlast;

    assign dbg_ad_ar_trk_full      = ar_trk_full;
    assign dbg_ad_ar_out_cnt       = ar_out_cnt;
    assign dbg_ad_ar_gate_ok       = ar_gate_ok;
    assign dbg_ad_ar_push          = ar_idt_push;
    assign dbg_ad_ar_pop           = ar_idt_pop;
    assign dbg_ad_host_arvalid     = host_axi_arvalid;
    assign dbg_ad_host_arready     = host_axi_arready;
    assign dbg_ad_fub_arvalid      = fub_axi_arvalid;
    assign dbg_ad_fub_arready      = fub_axi_arready;
    assign dbg_ad_wrapper_rd_busy  = wrapper_rd_busy;
    assign dbg_ad_fub_rvalid       = fub_axi_rvalid;
    assign dbg_ad_fub_rready       = fub_axi_rready;
    assign dbg_ad_fub_rlast        = fub_axi_rlast;
`endif

endmodule : bridge_2x2_axi5_native_dma_adapter
